ROOT = Path(__file__).resolve().parents[1]


def module(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    result = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(result)
    return result


manager = module('manage_meld_media', ROOT / 'scripts/manage_meld_media.py')
fixtures = module('media_configure_fixtures', ROOT / 'tests/test_configure_meld_media.py')


@unittest.skipUnless(os.name == 'posix', 'Linux systemd user services')
class ManageMeldMediaTests(unittest.TestCase):
    def setUp(self):
        self.fixture = fixtures.ConfigureMeldMediaTests('test_missing_explicit_disclosure_acceptance_writes_nothing')
        self.fixture.setUp()
        self.addCleanup(self.fixture.doCleanups)
        self.profile = self.fixture.root / 'profile'
        self.fixture._invoke(self.profile)
        programs = self.fixture.root / 'programs with spaces'
        programs.mkdir()
        self.options = {'fabric_port': 19461, 'python_dependencies': None}
        for key, name in [('python', 'python3'), ('nucleus', 'nucleus'), ('llama', 'llama-server')]:
            path = programs / name
            path.write_text('#!/bin/sh\nexit 0\n')
            path.chmod(0o700)
            self.options[key] = str(path)

    def test_prepare_is_private_secret_free_and_does_not_activate_or_initialize(self):
        with patch.object(manager, 'systemctl') as control, patch.object(manager.subprocess, 'run') as run:
            plan = manager.prepare(self.profile, self.options)
            control.assert_not_called()
            run.assert_not_called()
        self.assertFalse((self.profile / 'owner-state').exists())
        self.assertFalse((self.profile / 'bootstrap-invitation.json').exists())
        self.assertEqual(len(plan['units']), 3)
        self.assertEqual(plan['threads'], 4)
        for name in plan['units']:
            path = self.profile / 'systemd' / name
            raw = path.read_text()
            self.assertEqual(stat.S_IMODE(path.stat().st_mode), 0o600)
            self.assertIn('KillMode=control-group', raw)
            self.assertIn('UMask=0077', raw)
            self.assertIn('Restart=on-failure', raw)
            self.assertIn('StartLimitBurst=3', raw)
            for token_name in ['owner', 'generation', 'review']:
                self.assertNotIn((self.profile / (token_name + '-token')).read_text().strip(), raw)
            self.assertNotIn('/bin/sh', raw)
            if name.endswith('-generation.service'):
                for expected in ['"--threads" "4"', '"--strength" "0.65"', '"--memory-limit-bytes" "42949672960"', '"--reserve-memory-bytes" "4294967296"', '"--timeout-seconds" "1800"', '"--max-pixels" "262144"', str(self.profile / 'generation-token')]:
                    self.assertIn(expected, raw)
                self.assertIn(manager.load_profile(self.profile)['config']['generation_manifest_sha256'], raw)
        for path in (self.profile / 'logs').iterdir():
            self.assertEqual(stat.S_IMODE(path.stat().st_mode), 0o600)
        self.assertEqual(stat.S_IMODE((self.profile / 'systemd').stat().st_mode), 0o700)
        manager.reviewed_plan(self.profile)

    def test_bad_binary_and_profile_pin_fail_before_unit_writes(self):
        bad = dict(self.options, python='/bin/sh')
        with self.assertRaises(ValueError):
            manager.prepare(self.profile, bad)
        self.assertFalse((self.profile / 'systemd').exists())
        owner_path = self.profile / 'owner.json'
        owner = json.loads(owner_path.read_text())
        owner['meld']['generation_manifest_sha256'] = 'b' * 64
        owner_path.write_text(json.dumps(owner))
        with self.assertRaisesRegex(ValueError, 'manifest'):
            manager.prepare(self.profile, self.options)
        self.assertFalse((self.profile / 'systemd').exists())

    def test_missing_exact_disclosure_approval_fails_before_preparation(self):
        owner_path = self.profile / 'owner.json'
        owner = json.loads(owner_path.read_text())
        owner['approved_models'][-1].pop('allow_publisher_disclosed_lineage')
        owner_path.write_text(json.dumps(owner))
        with self.assertRaisesRegex(ValueError, 'owner exception'):
            manager.prepare(self.profile, self.options)
        self.assertFalse((self.profile / 'systemd').exists())

    def test_venv_interpreter_symlink_keeps_venv_spelling(self):
        path = Path(self.options['python'])
        link = path.with_name('python')
        link.symlink_to(path)
        options = dict(self.options, python=str(link))
        plan = manager.prepare(self.profile, options)
        generation = next(name for name in plan['units'] if name.endswith('-generation.service'))
        self.assertIn('ExecStart="' + str(link) + '"', (self.profile / 'systemd' / generation).read_text())

    def test_tampered_prepared_unit_or_unrelated_installed_unit_never_runs_commands(self):
        plan = manager.prepare(self.profile, self.options)
        name = next(iter(plan['units']))
        original = self.profile / 'systemd' / name
        raw = original.read_bytes()
        original.write_bytes(raw + b'\nExecStart=/bin/sh\n')
        with patch.object(manager.subprocess, 'run') as run:
            with self.assertRaises(ValueError):
                manager.install(self.profile)
            run.assert_not_called()
        original.write_bytes(raw)
        installed = self.fixture.root / 'user-units'
        installed.mkdir(mode=0o700)
        conflict = installed / name
        conflict.write_text('[Service]\nExecStart=/unrelated\n')
        conflict.chmod(0o600)
        with patch.object(manager, 'user_unit_directory', return_value=installed), patch.object(manager.subprocess, 'run') as run:
            with self.assertRaisesRegex(ValueError, 'unrelated'):
                manager.install(self.profile)
            run.assert_not_called()
        self.assertEqual(conflict.read_text(), '[Service]\nExecStart=/unrelated\n')
        self.assertFalse((self.profile / 'owner-state').exists())

    def test_authenticated_health_ignores_proxies_and_rejects_redirects_and_changed_pins(self):
        context = manager.load_profile(self.profile)
        servers = []
        observed = []
        for kind in ['gateway', 'generation', 'review']:
            class Handler(http.server.BaseHTTPRequestHandler):
                def do_GET(self):
                    label = self.server.kind
                    observed.append((label, self.headers.get('Authorization')))
                    if getattr(self.server, 'redirect', False):
                        self.send_response(302); self.send_header('Location', 'https://example.invalid/forbidden'); self.end_headers(); return
                    self.send_response(200)
                    self.send_header('Content-Type', 'application/json')
                    if label == 'gateway':
                        raw = b'{"service":"nucleus-inference","state":"gateway_online"}'
                    else:
                        raw = context['raw'][label + '-manifest.json']
                        self.send_header('X-Nucleus-Manifest-SHA256', 'f' * 64 if getattr(self.server, 'wrong_pin', False) else context['config'][label + '_manifest_sha256'])
                    self.end_headers(); self.wfile.write(raw)
                def log_message(self, *_args):
                    pass
            server = http.server.HTTPServer(('127.0.0.1', 0), Handler)
            server.kind = kind
            thread = threading.Thread(target=server.serve_forever, daemon=True)
            thread.start()
            self.addCleanup(server.server_close)
            self.addCleanup(server.shutdown)
            servers.append(server)
            context['endpoints'][kind] = ('http://127.0.0.1:' + str(server.server_port), '127.0.0.1', server.server_port)
        with patch.dict(os.environ, {'http_proxy': 'http://127.0.0.1:1', 'https_proxy': 'http://127.0.0.1:1', 'no_proxy': ''}):
            manager.health_once(context)
        self.assertEqual({kind for kind, _ in observed}, {'gateway', 'generation', 'review'})
        for kind, token in observed:
            self.assertEqual(token, 'Bearer ' + context['tokens'][kind])
        servers[1].wrong_pin = True
        with self.assertRaisesRegex(ValueError, 'pin'):
            manager.health_once(context)
        servers[1].wrong_pin = False
        servers[1].redirect = True
        with self.assertRaisesRegex(ValueError, 'redirect'):
            manager.health_once(context)

    def _worker_options(self):
        app = self.fixture.root / "meld app"
        for relative in ["artisan", "bootstrap/app.php", "composer.json", "vendor/autoload.php"]:
            path = app / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text("fixture only")
        php = Path(self.options["python"]).with_name("php8.5")
        php.write_text("#!/bin/sh\nexit 0\n"); php.chmod(0o700)
        env = self.profile / "meld.env"
        env.write_text(env.read_text() + "IMAGE_GENERATION_QUEUE_CONNECTION=nucleus-media\n")
        return dict(self.options, php=str(php), meld_app=str(app))

    def test_optional_worker_is_single_preflighted_and_drains_before_core_shutdown(self):
        options = self._worker_options()
        plan = manager.prepare(self.profile, options)
        self.assertEqual(len(plan["units"]), 4)
        names = manager.unit_names(self.profile, worker=True)
        raw = (self.profile / "systemd" / names["worker"]).read_text()
        self.assertIn("TimeoutStopSec=5460", raw)
        self.assertIn("After=" + " ".join(names[kind] for kind in ["generation", "review", "gateway"]), raw)
        self.assertIn('"queue:work" "nucleus-media" "--queue=nucleus-media" "--sleep=1" "--tries=1" "--timeout=5400" "--memory=512"', raw)
        self.assertIn('"meld:check-nucleus-profile"', raw)
        self.assertIn('"wait-health"', raw)
        self.assertIn("EnvironmentFile=" + str(self.profile / "meld.env") + "\n", raw)
        self.assertIn('"/usr/bin/flock" "--no-fork" "--exclusive" "--nonblock" "--conflict-exit-code" "73"', raw)
        self.assertIn(str(manager.worker_lock_path(Path(options["meld_app"]))), raw)
        self.assertIn("NUCLEUS_INFERENCE_API_KEY", (self.profile / "meld.env").read_text())
        unset = next(line for line in raw.splitlines() if line.startswith("UnsetEnvironment="))
        self.assertNotIn("NUCLEUS_INFERENCE_API_KEY", unset)
        for name in ["owner", "generation", "review"]:
            self.assertNotIn((self.profile / (name + "-token")).read_text().strip(), raw)
        calls = []
        with patch.object(manager, "systemctl", side_effect=lambda args, **kwargs: calls.append(args)):
            manager.stop(self.profile)
        self.assertEqual(calls[0][0], "disable")
        self.assertEqual(calls[1][:2], ["stop", "--no-block"])
        self.assertIn(names["worker"], calls[1])
        # Verify ordering and quoting using the installed systemd parser; no unit
        # or PHP fixture is installed or executed by this operation.
        if Path(manager.ANALYZE).is_file():
            result = subprocess.run([manager.ANALYZE, "--user", "verify", *[str(self.profile / "systemd" / name) for name in plan["units"]]], capture_output=True, text=True, timeout=20, env=manager.user_environment())
            if not any(marker in result.stderr for marker in ["Failed to initialize manager", "Failed to connect to bus", "No medium found"]):
                self.assertEqual(result.returncode, 0, result.stderr)
                self.assertNotIn("ignoring:", result.stderr)

    def test_singleton_guard_rejects_active_or_enabled_other_profile_before_mutation(self):
        options = self._worker_options()
        manager.prepare(self.profile, options)
        other = 'nucleus-meld-0123456789ab-worker.service'
        for active, enabled in [('active', 'disabled'), ('deactivating', 'disabled'), ('inactive', 'enabled')]:
            calls = []
            def read_only_control(args, **kwargs):
                calls.append(args)
                if args[0] == 'list-units':
                    return subprocess.CompletedProcess(args, 0, stdout=other + ' loaded active running fixture\n')
                if args[0] == 'show':
                    return subprocess.CompletedProcess(args, 0, stdout='WorkingDirectory=' + options['meld_app'] + '\nActiveState=' + active + '\nUnitFileState=' + enabled + '\n')
                self.fail('guard attempted a systemd mutation: ' + repr(args))
            with self.subTest(active=active, enabled=enabled), patch.object(manager, 'user_unit_directory', return_value=self.fixture.root / 'units'), patch.object(manager, 'systemctl', side_effect=read_only_control), patch.object(manager.subprocess, 'run') as run, patch.object(manager.socket, 'socket') as socket:
                with self.assertRaisesRegex(ValueError, 'explicitly drain and disable'):
                    manager.install(self.profile)
                run.assert_not_called()
                socket.assert_not_called()
                self.assertFalse((self.profile / 'owner-state').exists())
                self.assertEqual([args[0] for args in calls], ['list-units', 'show'])

    def test_singleton_guard_allows_drained_or_different_application_workers(self):
        options = self._worker_options()
        plan = manager.prepare(self.profile, options)
        context = manager.load_profile(self.profile)
        other = 'nucleus-meld-0123456789ab-worker.service'
        for directory, active, enabled in [(options['meld_app'], 'inactive', 'disabled'), (str(self.fixture.root / 'another-app'), 'active', 'enabled')]:
            responses = [subprocess.CompletedProcess([], 0, stdout=other + ' loaded active running fixture\n'), subprocess.CompletedProcess([], 0, stdout='WorkingDirectory=' + directory + '\nActiveState=' + active + '\nUnitFileState=' + enabled + '\n')]
            with self.subTest(directory=directory), patch.object(manager, 'systemctl', side_effect=responses):
                manager.assert_single_worker(context, plan, self.fixture.root / 'units')
        # The lock is canonical-app scoped, independent of profile path.
        lock = manager.worker_lock_path(Path(options['meld_app']).resolve())
        self.assertNotIn(str(self.profile), str(lock))
        self.assertEqual(lock, manager.worker_lock_path(Path(options['meld_app']).resolve()))

    @unittest.skipUnless(Path('/usr/bin/flock').is_file(), 'Linux flock unavailable')
    def test_worker_flock_denies_a_second_consumer_until_the_first_drains(self):
        lock = self.fixture.root / 'shared-queue.lock'
        command = [manager.FLOCK, '--no-fork', '--exclusive', '--nonblock', '--conflict-exit-code', '73', str(lock), '/usr/bin/true']
        with lock.open('wb') as held:
            fcntl.flock(held, fcntl.LOCK_EX | fcntl.LOCK_NB)
            self.assertEqual(subprocess.run(command, capture_output=True, timeout=5).returncode, 73)
        self.assertEqual(subprocess.run(command, capture_output=True, timeout=5).returncode, 0)

    def test_runtime_deadlines_follow_profile_and_worker_requires_reviewed_bounds(self):
        options = self._worker_options()
        plan = manager.prepare(self.profile, options)
        for name in plan['units']:
            if name.endswith('-review.service'):
                self.assertIn('"--timeout-seconds" "600"', (self.profile / 'systemd' / name).read_text())
            if name.endswith('-generation.service'):
                self.assertIn('"--timeout-seconds" "1800"', (self.profile / 'systemd' / name).read_text())
        env = self.profile / 'meld.env'
        env.write_text(env.read_text().replace('POSITRONIC_IMAGE_REVIEW_TIMEOUT=600', 'POSITRONIC_IMAGE_REVIEW_TIMEOUT=1800'))
        with self.assertRaisesRegex(ValueError, 'generation1800/review600'):
            manager.units(manager.load_profile(self.profile), options)
        # Non-worker profiles keep their existing explicitly configured deadline.
        rendered = manager.units(manager.load_profile(self.profile), self.options)
        review = next(raw for name, raw in rendered.items() if name.endswith('-review.service'))
        self.assertIn(b'"--timeout-seconds" "1800"', review)

    def test_stored_plan_port_type_is_revalidated(self):
        manager.prepare(self.profile, self.options)
        path = self.profile / "systemd/plan.json"
        plan = json.loads(path.read_text())
        plan["options"]["fabric_port"] = "19461\nExecStart=/bin/sh"
        path.write_text(json.dumps(plan))
        with self.assertRaisesRegex(ValueError, "distinct integer"):
            manager.reviewed_plan(self.profile)

    def test_strength_is_validated_before_writes_and_again_for_stored_plans(self):
        for value in [0, -0.1, 1.01, float("nan"), float("inf"), True, "1\nExecStart=/bin/sh"]:
            with self.subTest(value=value):
                with self.assertRaisesRegex(ValueError, "strength must be a finite number"):
                    manager.prepare(self.profile, dict(self.options, strength=value))
                self.assertFalse((self.profile / "systemd").exists())
        plan = manager.prepare(self.profile, dict(self.options, strength=1.0))
        generation = next(name for name in plan["units"] if name.endswith("-generation.service"))
        self.assertIn('"--strength" "1.0"', (self.profile / "systemd" / generation).read_text())
        self.assertEqual(plan["options"]["strength"], 1.0)
        manager.reviewed_plan(self.profile)
        path = self.profile / "systemd/plan.json"
        plan["options"]["strength"] = "1\nExecStart=/bin/sh"
        path.write_text(json.dumps(plan))
        with self.assertRaisesRegex(ValueError, "strength must be a finite number"):
            manager.reviewed_plan(self.profile)

    def _fake_bootstrap(self, args, **kwargs):
        state = Path(kwargs["env"]["NUCLEUS_HOME"]) / "state.json"
        if args[1] == "init":
            state.parent.mkdir(mode=0o700)
            state.write_text(json.dumps({"public": {"node_id": "fixture-owner", "fabric_id": ""}}))
            state.chmod(0o600)
        elif args[1] == "invite":
            state.write_text(json.dumps({"public": {"node_id": "fixture-owner", "owner_id": "fixture-owner", "fabric_id": "fixture-fabric", "endpoint": args[3]}}))
            invitation = Path(args[5]); invitation.write_text("fixture-only")
            invitation.chmod(0o600)
        else:
            self.fail("unexpected bootstrap command")
        return subprocess.CompletedProcess(args, 0)

    def test_install_enables_only_after_health_and_stops_on_failed_health(self):
        manager.prepare(self.profile, self.options)
        installed = self.fixture.root / "installed-units"
        events = []
        with patch.object(manager, "user_unit_directory", return_value=installed), patch.object(manager.socket, "socket"), patch.object(manager.subprocess, "run", side_effect=self._fake_bootstrap), patch.object(manager, "systemctl", side_effect=lambda args, **kwargs: events.append(args[0])), patch.object(manager, "health_once", side_effect=lambda context: events.append("health")):
            names = manager.install(self.profile)
        self.assertEqual(events, ["daemon-reload", "start", "health", "enable"])
        self.assertEqual(set(path.name for path in installed.iterdir()), set(names))
        for path in installed.iterdir():
            self.assertEqual(stat.S_IMODE(path.stat().st_mode), 0o600)
        # A separate fresh profile makes failure cleanup independent of the
        # successfully installed fixture. All systemd/bootstrap calls are mocks.
        failed = self.fixture.root / "failed-profile"
        self.fixture._invoke(failed)
        manager.prepare(failed, self.options)
        events = []
        with patch.object(manager, "user_unit_directory", return_value=self.fixture.root / "failed-units"), patch.object(manager.socket, "socket"), patch.object(manager.subprocess, "run", side_effect=self._fake_bootstrap), patch.object(manager, "systemctl", side_effect=lambda args, **kwargs: events.append(args[0])), patch.object(manager, "health_once", side_effect=ValueError("wrong pin")), patch.object(manager.time, "monotonic", side_effect=[0, 61]):
            with self.assertRaisesRegex(RuntimeError, "persistence was not enabled"):
                manager.install(failed)
        self.assertEqual(events, ["daemon-reload", "start", "disable"])

